def test_what_the_update_prints_carries_no_emoji(tmp_path, capsys):
    root = _project(tmp_path, V095)
    _apply(root)
    printed = capsys.readouterr().out
    for char in printed:
        assert ord(char) < 0x2190 or char in '→─', repr(char)

